const input = $('Extract Twilio Fields').item.json;
const numMedia = parseInt(input.NumMedia || "0", 10);
const mediaType = (input.MediaContentType0 || "").toLowerCase();
const bodyText = (input.Body || "").trim();

const manualMode = ["1","2","3"].includes(bodyText) ? bodyText : null;

// Video is always unambiguous (Mode 3). Photo mode (1 vs 2) can NOT be
// decided from a single incoming message -- WhatsApp/Twilio delivers each
// photo as its OWN separate webhook (NumMedia is basically always 1 per
// call, even if the trader picked several photos in their gallery), so
// Session Matching has to finalize mode 1-vs-2 once all photos + the voice
// note have arrived, not here.
let detectedMode = "pending";
if (mediaType.startsWith("video/")) detectedMode = "3";

const isMedia = mediaType.startsWith("image/") || mediaType.startsWith("video/");
const isAudio = mediaType.startsWith("audio/");
const isManualModeSelection = manualMode !== null && !isMedia && !isAudio;

const allMediaUrls = [input.MediaUrl0, input.MediaUrl1, input.MediaUrl2, input.MediaUrl3, input.MediaUrl4]
  .slice(0, Math.max(numMedia, 1))
  .filter(Boolean);
const mediaUrlsJoined = allMediaUrls.join(',');

return { json: { ...input, detectedMode, manualMode, isMedia, isAudio, isManualModeSelection, mediaUrlsJoined } };

const current = $input.item.json;
const sessionRows = $('Google Sheets').all();
const existingSession = sessionRows.length > 0 ? sessionRows[0].json : null;

const hasExistingMedia = !!(existingSession && existingSession.MediaUrl);
const hasExistingAudio = !!(existingSession && existingSession.AudioUrl);

// Accumulate photo URLs across separate incoming messages: WhatsApp/Twilio
// delivers each photo as its own webhook (NumMedia is basically always 1
// per call), not bundled together, so a multi-photo Mode 2 session has to
// be built up message-by-message until the voice note finally arrives.
let mergedMediaUrl;
if (current.isMedia) {
  const stillAccumulating = hasExistingMedia && !hasExistingAudio;
  const existingUrls = stillAccumulating ? existingSession.MediaUrl.split(',').filter(Boolean) : [];
  const combined = [...existingUrls, ...current.mediaUrlsJoined.split(',').filter(Boolean)];
  mergedMediaUrl = combined.slice(0, 5).join(',');
} else {
  mergedMediaUrl = existingSession ? existingSession.MediaUrl : undefined;
}
const finalHasMedia = !!mergedMediaUrl;

const mergedAudioUrl = current.isAudio ? current.MediaUrl0 : (existingSession ? existingSession.AudioUrl : undefined);
const finalHasAudio = hasExistingAudio || current.isAudio;

let sessionCase;
if (current.isManualModeSelection) {
  sessionCase = "MODE_SELECTED";
} else if (finalHasMedia && finalHasAudio) {
  sessionCase = "COMPLETE";
} else if (current.isMedia && !finalHasAudio) {
  sessionCase = "MEDIA_ONLY";
} else if (current.isAudio && !finalHasMedia) {
  sessionCase = "AUDIO_ONLY";
} else {
  sessionCase = "INVALID";
}

// Finalize mode. IMPORTANT: a video (Mode 3) always arrives in ITS OWN
// webhook, separate from the voice note that later completes the session.
// By the time the voice-note webhook fires (triggering COMPLETE), that
// webhook's own current.detectedMode is 'pending' (audio isn't video) --
// so we must check whether a video was already confirmed on an EARLIER
// webhook (existingSession.DetectedMode === '3') before falling back to
// the photo-count-based Mode 1 vs 2 decision, otherwise a Mode 3 session
// gets silently downgraded to Mode 1 the moment the voice note lands.
const priorModeWasVideo = existingSession && String(existingSession.DetectedMode) === '3';
const photoCount = mergedMediaUrl ? mergedMediaUrl.split(',').filter(Boolean).length : 0;
let mergedDetectedMode;
let autoDetected;
if (current.manualMode) {
  mergedDetectedMode = current.manualMode;
  autoDetected = "No";
} else if (current.detectedMode === "3") {
  mergedDetectedMode = "3";
  autoDetected = "Yes";
} else if (priorModeWasVideo) {
  mergedDetectedMode = "3";
  autoDetected = "Yes";
} else if (sessionCase === "COMPLETE") {
  mergedDetectedMode = photoCount > 1 ? "2" : "1";
  autoDetected = "Yes";
} else if (existingSession && existingSession.DetectedMode) {
  mergedDetectedMode = existingSession.DetectedMode;
  autoDetected = existingSession.AutoDetected || "";
} else {
  mergedDetectedMode = "pending";
  autoDetected = "";
}

return { json: { ...current, sessionCase, MediaUrl0: mergedMediaUrl, AudioUrl: mergedAudioUrl, detectedMode: mergedDetectedMode, autoDetected, photoCount } };

