const data = $input.item.json;
const mood = (data.music_mood || "").toLowerCase();
let music = "clean-minimal.mp3";
if(mood === "energetic") music = "energetic-upbeat.mp3";
else if(mood === "warm") music = "warm-acoustic.mp3";
else if(mood === "bold") music = "bold-dramatic.mp3";
return { json: { ...data, selected_music: music } };

const llamaResponse = $input.item.json;
const content = (llamaResponse.choices && llamaResponse.choices[0] && llamaResponse.choices[0].message && llamaResponse.choices[0].message.content) || "{}";
let extracted = {};
try { extracted = JSON.parse(content); } catch (e) { extracted = {}; }
const session = $('Session Matching').item.json;
const transcript = ($('Groq Whisper Transcription').item.json.text) || '';
return { json: {
  From: session.From,
  MediaUrl0: session.MediaUrl0,
  AudioUrl: session.AudioUrl,
  detectedMode: session.detectedMode,
  autoDetected: session.autoDetected,
  RequestStartTime: session.RequestStartTime,
  transcript: transcript,
  product_name: extracted.product_name || '',
  price: extracted.price || '',
  key_feature: extracted.key_feature || '',
  tagline: extracted.tagline || '',
  language: extracted.language || '',
  music_mood: extracted.music_mood || ''
} };

const renderResult = $input.item.json;
const productData = $('Music Mapping').item.json;
const startTime = productData.RequestStartTime ? new Date(productData.RequestStartTime).getTime() : null;
const processingTimeSeconds = startTime ? Math.round((Date.now() - startTime) / 1000) : null;
return { json: {
  ...productData,
  finalVideoUrl: renderResult.finalVideoUrl || renderResult.final_video_url || '',
  exitCode: renderResult.exitCode !== undefined ? renderResult.exitCode : 0,
  error: renderResult.error || '',
  durationSeconds: renderResult.durationSeconds || renderResult.duration_seconds || null,
  fileSizeMB: renderResult.fileSizeMB || renderResult.file_size_mb || null,
  processingTimeSeconds
} };

const now = Date.now();
const staleRows = [];
for (const item of $input.all()) {
  const ts = item.json.SessionTimestamp;
  if (!ts) continue;
  const ageMs = now - new Date(ts).getTime();
  if (ageMs > 30 * 60 * 1000) {
    staleRows.push({ json: { rowNumber: item.json.row_number, From: item.json.PhoneNumber } });
  }
}
staleRows.sort((a, b) => b.json.rowNumber - a.json.rowNumber);
return staleRows;
